import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"admin.yaml","description":"Default :8081. Disk static_dir wins over embed; empty string disables the UI. enabled=false skips the admin listener only.","frontmatter":{"title":"admin.yaml","description":"Default :8081. Disk static_dir wins over embed; empty string disables the UI. enabled=false skips the admin listener only."},"headers":[],"relativePath":"en/guide/config/admin.yaml.md","filePath":"en/guide/config/admin.yaml.md","lastUpdated":1790057721000}`),a={name:`en/guide/config/admin.yaml.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="admin-yaml" tabindex="-1">admin.yaml <a class="header-anchor" href="#admin-yaml" aria-label="Permalink to “admin.yaml”">​</a></h1><p>File: <code>admin.yaml</code>. Prefix <code>KIRIVERS_ADMIN_</code>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Meaning</th><th>When to change</th></tr></thead><tbody><tr><td><code>addr</code></td><td>string</td><td><code>:8081</code></td><td>Listen</td><td>Bind <code>127.0.0.1:8081</code> or LAN in production</td></tr><tr><td><code>enabled</code></td><td>bool</td><td><code>true</code></td><td><code>false</code> <strong>skips the admin listener only</strong> (no admin API / SPA / proxy). Client plane and health still run</td><td>Client-only hosts</td></tr><tr><td><code>mode</code></td><td>string</td><td>example <code>debug</code></td><td>Combined Gin mode</td><td>Production <code>release</code></td></tr><tr><td><code>tls_cert</code> / <code>tls_key</code></td><td>path</td><td><code>&quot;&quot;</code></td><td>HTTPS only when both are set</td><td>Fill when this plane terminates TLS; otherwise terminate at the reverse proxy</td></tr><tr><td><code>trusted_proxies</code></td><td>string[]</td><td><code>[]</code></td><td>Empty = do not trust <code>X-Forwarded-For</code></td><td>After an admin reverse proxy</td></tr><tr><td><code>static_dir</code></td><td>path</td><td><code>frontend/dist</code></td><td>See below</td><td>Usually leave default</td></tr></tbody></table><h2 id="admin-ui-files" tabindex="-1">Admin UI files <a class="header-anchor" href="#admin-ui-files" aria-label="Permalink to “Admin UI files”">​</a></h2><p>Official binaries embed the console. Precedence:</p><ol><li><code>static_dir</code> is the <strong>empty string</strong> → <strong>UI off</strong> even if embed has <code>index.html</code>.</li><li>Non-empty <code>static_dir</code> with disk <code>index.html</code> → disk (rebuild Go is not required after replacing dist).</li><li>Else embed FS has <code>index.html</code> → embed.</li><li>Neither → API-only (<code>GET /</code> is JSON 404).</li></ol><p><code>static_dir</code> is the admin UI tree (or empty to disable the UI). The VitePress docs site is not the console. Official Release binaries already embed the UI; copying <code>frontend/dist</code> is not a user install step.</p><p>In production the admin plane <strong>reverse-proxies</strong> <code>/api/v1/projects/**</code> to this process’s client plane for console check/integrity previews.</p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};